var frontmatter = { "title": "Custom Pages" };
var _markdown = "\n\n# Custom Pages [#custom-pages]\n\nThe Onboarding component supports fully custom pages through its children props.\n\n## Basic Custom Page [#basic-custom-page]\n\n```jsx\nconst CustomPage = ({ title, description, color }) => (\n  <View style={[styles.page, { backgroundColor: color }]}>\n    <View style={styles.content}>\n      <Text style={styles.title}>{title}</Text>\n      <Text style={styles.description}>{description}</Text>\n    </View>\n  </View>\n);\n\nconst App = () => (\n  <Onboarding>\n    <CustomPage\n      title=\"Welcome\"\n      description=\"Start your journey with us\"\n      color=\"#FF6B6B\"\n    />\n    <CustomPage\n      title=\"Features\"\n      description=\"Discover what we offer\"\n      color=\"#4ECDC4\"\n    />\n    <CustomPage\n      title=\"Get Started\"\n      description=\"Ready to begin?\"\n      color=\"#45B7D1\"\n    />\n  </Onboarding>\n);\n```\n\n## Animated Custom Page [#animated-custom-page]\n\n```jsx\nconst AnimatedPage = ({ title, image, onPress }) => {\n  const fadeAnim = useRef(new Animated.Value(0)).current;\n  const slideAnim = useRef(new Animated.Value(50)).current;\n\n  useEffect(() => {\n    Animated.parallel([\n      Animated.timing(fadeAnim, {\n        toValue: 1,\n        duration: 1000,\n        useNativeDriver: true,\n      }),\n      Animated.timing(slideAnim, {\n        toValue: 0,\n        duration: 1000,\n        useNativeDriver: true,\n      }),\n    ]).start();\n  }, []);\n\n  return (\n    <View style={styles.container}>\n      <Animated.Image\n        source={image}\n        style={[\n          styles.image,\n          {\n            opacity: fadeAnim,\n            transform: [{ translateY: slideAnim }],\n          },\n        ]}\n      />\n      <Animated.Text\n        style={[\n          styles.title,\n          {\n            opacity: fadeAnim,\n            transform: [{ translateY: slideAnim }],\n          },\n        ]}\n      >\n        {title}\n      </Animated.Text>\n    </View>\n  );\n};\n```\n\n## Interactive Custom Page [#interactive-custom-page]\n\n```jsx\nconst InteractivePage = ({ onComplete }) => {\n  const [name, setName] = useState('');\n  \n  return (\n    <View style={styles.container}>\n      <Text style={styles.title}>Welcome!</Text>\n      <TextInput\n        style={styles.input}\n        placeholder=\"Enter your name\"\n        value={name}\n        onChangeText={setName}\n      />\n      <TouchableOpacity\n        style={styles.button}\n        onPress={() => onComplete(name)}\n      >\n        <Text style={styles.buttonText}>Continue</Text>\n      </TouchableOpacity>\n    </View>\n  );\n};\n```\n\n## Layout Examples [#layout-examples]\n\n```jsx\nconst styles = StyleSheet.create({\n  container: {\n    flex: 1,\n    justifyContent: 'center',\n    alignItems: 'center',\n    padding: 20,\n  },\n  image: {\n    width: 200,\n    height: 200,\n    marginBottom: 20,\n  },\n  title: {\n    fontSize: 24,\n    fontWeight: 'bold',\n    marginBottom: 10,\n  },\n  description: {\n    fontSize: 16,\n    textAlign: 'center',\n    color: '#666',\n  },\n  input: {\n    width: '100%',\n    height: 40,\n    borderWidth: 1,\n    borderColor: '#ccc',\n    borderRadius: 8,\n    paddingHorizontal: 10,\n    marginBottom: 20,\n  },\n  button: {\n    backgroundColor: '#007AFF',\n    paddingHorizontal: 20,\n    paddingVertical: 10,\n    borderRadius: 8,\n  },\n  buttonText: {\n    color: '#fff',\n    fontWeight: 'bold',\n  },\n});\n```\n\n## Live Example [#live-example]\n\nTry this example on [Expo Snack](https://snack.expo.dev/@lekgwaraj/react-native-app-onboard-custom?platform=ios)\n";
